class DColoringEdgesOnTree {

public:

    vii g;

    vi res;

    map<pi, int> mp;



    void dfs(int u, int p) {

        int c = 1;

        for(auto& to : g[u]){

            if(p != -1 && c == res[mp[make_pair(u, p)]]) c++;

            if(to == p) continue;

            res[mp[make_pair(u, to)]] = c;

            dfs(to, u);

            c++;

        }

    }



	void solve(std::istream& in, std::ostream& out) {

	    int n;

	    in >> n;

	    g = vii(n);

	    for(int i=0; i<n-1; i++){

	        int a, b;

	        in >> a >> b;

	        --a; --b;

	        g[a].push_back(b);

	        g[b].push_back(a);

	        mp[make_pair(a, b)] = mp[make_pair(b, a)] = i;

	    }



        res = vi(n-1);

        dfs(0, -1);



        out << *max_element(res.begin(), res.end()) << enl;

        for(int i=0; i<n-1; i++) out << res[i] << enl;

	}

};





int main() {

    cin.tie(nullptr);

    ios_base::sync_with_stdio(false);

	DColoringEdgesOnTree solver;

	std::istream& in(std::cin);

	std::ostream& out(std::cout);

	solver.solve(in, out);

	return 0;

}
